<?php
require __DIR__.'/wp-fixture.php';
$checks=0;
function assert_test($ok,$name){global $checks;if(!$ok)throw new Exception('FAIL '.$name);$checks++;echo "PASS $name\n";}
function call_action($order,$action,$data=[]){$s=gor_state($order);return gor_api(new WP_REST_Request(['id'=>$order->id,'version'=>$s['version'],'action'=>$action]+$data));}
$o=new WC_Order(12001);$GLOBALS['orders'][$o->id]=$o;
$old=new WC_Order(12000);$old->created='2026-09-09 23:59:59';$GLOBALS['orders'][$old->id]=$old;
assert_test(gor_managed($o)&&!gor_managed($old),'cutover boundary');
assert_test(!apply_filters('woocommerce_can_reduce_order_stock',true,$o),'new order automatic stock blocked');
assert_test(apply_filters('woocommerce_can_reduce_order_stock',true,$old),'legacy stock unchanged');
require __DIR__.'/../../wordpress/wp-content/mu-plugins/rusky-dotypos-fiscalization.php';
assert_test(!rdf_should_fiscalize($o),'real fiscal module guarded for new orders');
assert_test(rdf_should_fiscalize($old),'real fiscal decision unchanged for legacy order');
rdf_retry_fiscalization($o->id);
rdf_stock_fallback($o);
assert_test($o->meta===[],'background retry and stock fallback leave new order untouched');
assert_test(apply_filters('pre_http_request',false,[],'https://api.dotykacka.cz') instanceof WP_Error,'sandbox blocks outbound HTTP');
assert_test(apply_filters('pre_wp_mail',null,['to'=>'customer@example.invalid'])===true,'sandbox intercepts mail');
$GLOBALS['allowed']=false;assert_test(!gor_permission(new WP_REST_Request(['id'=>$o->id])),'permission denied without capability');$GLOBALS['allowed']=true;
$GLOBALS['options']['_gor_lock_'.$o->id]=time();assert_test(call_action($o,'edit') instanceof WP_Error,'concurrent request rejected');unset($GLOBALS['options']['_gor_lock_'.$o->id]);
$r=call_action($o,'approve',['dispatch_date'=>'2026-09-12']);
assert_test($r['state']['status']==='approved','WordPress normal approval');
assert_test(count($o->meta['_gor_sandbox_effects'])===1,'one fiscal and stock effect');
assert_test($o->get_total()===40&&count($o->items)===2,'Woo source order unchanged');
assert_test($r['state']['mail']['confirmation']['transport']==='sandbox-capture','confirmation captured not sent');
assert_test(strpos($r['state']['mail']['confirmation']['message']['html'],'12.09.2026')!==false,'dispatch date in actual generated confirmation');
assert_test(call_action($o,'approve',['dispatch_date'=>'2026-09-12']) instanceof WP_Error,'API double approval rejected');
$o2=new WC_Order(12002);$o2->paid=true;$o2->method='woocommerce_payments';$GLOBALS['orders'][$o2->id]=$o2;
call_action($o2,'edit');
$r=call_action($o2,'save',['quote'=>['lines'=>[['product_id'=>2,'quantity'=>'1','price'=>'30.50']]],'reason'=>'Пельмени отсутствуют']);
assert_test($r['state']['quote']['lines'][0]['name']==='Продукты к заказу','product name comes from catalog');
assert_test(Gastronom\OrderReview\Review::balance($r['state'])===-600,'API refund calculation');
$GLOBALS['options']['gor_sandbox_fail_mail']=true;$r=call_action($o2,'proposal');assert_test($r['state']['mail']['proposal-1']['status']==='failed','mail failure retained');
assert_test(call_action($o2,'agree',['consent_note'=>'reply']) instanceof WP_Error,'cannot consent to unsent mail');
$GLOBALS['options']['gor_sandbox_fail_mail']=false;$r=call_action($o2,'mail_retry',['key'=>'proposal-1']);assert_test($r['state']['mail']['proposal-1']['attempts']===2,'retry mail only');
call_action($o2,'agree',['consent_note'=>'reply #42']);
$GLOBALS['options']['gor_sandbox_fail_effect']=true;$r=call_action($o2,'approve',['dispatch_date'=>'2026-09-12']);assert_test($r['state']['status']==='error'&&!isset($r['state']['mail']['confirmation']),'failed fiscal execution does not send confirmation');
$GLOBALS['options']['gor_sandbox_fail_effect']=false;$r=call_action($o2,'retry');assert_test($r['state']['status']==='approved'&&count($o2->meta['_gor_sandbox_effects'])===1,'retry completes one effect');
$plan=array_values($o2->meta['_gor_sandbox_effects'])[0]['plan'];assert_test($plan['total_cents']===3400&&$plan['delivery']['cod_cents']===0&&count($plan['receipt']['items'])===1,'corrected fulfillment payload, no COD on prepaid');
assert_test($o2->get_total()===40&&count($o2->items)===2,'prepaid source order immutable');
$o3=new WC_Order(12003);$o3->method='woocommerce_payments';$GLOBALS['orders'][$o3->id]=$o3;call_action($o3,'edit');
$s=gor_state($o3);$s['quote']['lines'][0]['qty']=3000;$s['quote']['lines'][0]['rate']=33;$s['quote']['lines'][0]['total']=100;
$q=gor_normalize_quote(['lines'=>[['key'=>'item-1','product_id'=>1,'quantity'=>'3','price'=>'0.33']]],$s);
assert_test($q['lines'][0]['total']===100,'unchanged discounted line preserves exact cent total');
$q=gor_normalize_quote(['lines'=>[['product_id'=>4,'quantity'=>'0.375','price'=>'20','weighted'=>false,'weight_confirmed'=>false]]],$s);
assert_test($q['lines'][0]['unit']==='kg'&&$q['lines'][0]['weight_pending']&&$q['lines'][0]['total']===750,'server derives weight semantics despite client tampering');
$o3->paid=true;$r=call_action($o3,'cancel_edit');assert_test($r instanceof WP_Error&&gor_state($o3)['paid']===4000,'late payment reconciled before command');
$o4=new WC_Order(12004);$GLOBALS['orders'][$o4->id]=$o4;call_action($o4,'edit');$o4->items=[new WC_Order_Item_Product(1,7),new WC_Order_Item_Product(2,29.5)];assert_test(call_action($o4,'cancel_edit') instanceof WP_Error,'out-of-band source item modification blocked');
echo "\n$checks WordPress adapter checks passed.\n";
$oCancel=new WC_Order(13000);$oCancel->paid=true;$oCancel->method='woocommerce_payments';$GLOBALS['orders'][$oCancel->id]=$oCancel;
call_action($oCancel,'edit');$r=call_action($oCancel,'save',['quote'=>['lines'=>[]],'reason'=>'Нет всех товаров']);
assert_test($r['state']['quote']['shipping']===0&&Gastronom\OrderReview\Review::balance($r['state'])===-4000,'full cancellation proposes full prepaid refund');
call_action($oCancel,'proposal');call_action($oCancel,'agree',['consent_note'=>'reply cancel']);$r=call_action($oCancel,'approve');
assert_test($r['state']['status']==='cancelled'&&!isset($oCancel->meta['_gor_sandbox_effects']),'approved cancellation has no sale or stock deduction');
call_action($oCancel,'bank',['iban'=>'SK3112000000198742637541','holder'=>'Anna','bank_consent'=>true]);$r=call_action($oCancel,'refund',['amount'=>'40','reference'=>'bank-cancel']);
assert_test(Gastronom\OrderReview\Review::balance($r['state'])===0,'cancelled prepaid order supports manual full refund');
$oRevert=new WC_Order(13001);$GLOBALS['orders'][$oRevert->id]=$oRevert;call_action($oRevert,'edit');call_action($oRevert,'save',['quote'=>['lines'=>[['product_id'=>1,'quantity'=>'1','price'=>'6']]],'reason'=>'Нет второй позиции']);call_action($oRevert,'proposal');call_action($oRevert,'edit');$r=call_action($oRevert,'cancel_edit');
assert_test($r['state']['status']==='editing'&&call_action($oRevert,'approve',['dispatch_date'=>'2026-09-12']) instanceof WP_Error,'reverting a sent proposal still requires fresh consent');
assert_test(call_action($oRevert,'mail_retry',['key'=>'proposal-1']) instanceof WP_Error,'old proposal cannot be resent after revision changed');
$oWeight=new WC_Order(13002);$oWeight->items=[new WC_Order_Item_Product(4,6),new WC_Order_Item_Product(2,30.5)];$GLOBALS['orders'][$oWeight->id]=$oWeight;
$GLOBALS['stock'][4]=4;$GLOBALS['product_meta'][4]['_gastronom_cash_stock_kg']=2.0;
gor_reserve($oWeight,gor_state($oWeight)['quote']);
assert_test(gor_hold_book()[$oWeight->id][4]['milli']===500,'unknown weight reserves maximum pack mass');
call_action($oWeight,'edit');$r=call_action($oWeight,'save',['quote'=>['lines'=>[['product_id'=>4,'quantity'=>'0.375','price'=>'20','weight_confirmed'=>true]]],'reason'=>'Уточнили вес','cause'=>'weight']);
call_action($oWeight,'proposal');call_action($oWeight,'agree',['consent_note'=>'weight reply']);$r=call_action($oWeight,'approve',['dispatch_date'=>'2026-09-12']);
assert_test($r['state']['status']==='approved'&&abs($GLOBALS['product_meta'][4]['_gastronom_cash_stock_kg']-1.625)<.000001,'weight approval deducts actual kg, not reserved maximum');
assert_test($GLOBALS['stock'][4]===3&&gor_held_quantity(4)===0,'remaining kilograms converted to safe piece capacity');
$row=gor_finance_row($oCancel);assert_test($row['original_cents']===4000&&$row['approved_cents']===0&&$row['refunded_cents']===4000,'finance export distinguishes original sale, cancellation and bank refund');
$oRecovery=new WC_Order(13003);$GLOBALS['orders'][$oRecovery->id]=$oRecovery;$state=Gastronom\OrderReview\Review::command(gor_state($oRecovery),'approve',['version'=>1,'order_id'=>13003,'cod'=>true,'dispatch_date'=>'2026-09-12'],'2026-09-10','1');gor_save($oRecovery,$state);
$GLOBALS['options']['_gor_lock_13003']=time();
try{gor_recover_order($oRecovery,'worker stopped');assert_test(false,'active recovery');}catch(DomainException $e){assert_test(true,'recovery refuses recent active worker');}
$GLOBALS['options']['_gor_lock_13003']=time()-601;gor_recover_order($oRecovery,'PHP worker terminated; journal inspected');
assert_test(gor_state($oRecovery)['status']==='error'&&!isset($GLOBALS['options']['_gor_lock_13003']),'operator recovery restores reconciliation after crashed request');

$oCodDate=new WC_Order(13004);$oCodDate->paid=true;$GLOBALS['orders'][$oCodDate->id]=$oCodDate;
assert_test(gor_state($oCodDate)['paid']===0,'COD Woo paid date does not invent original-amount receipt');
