$r=call_action($oPreflight,'approve',['dispatch_date'=>'2026-09-12']);
assert_test($r instanceof WP_Error&&gor_state($oPreflight)['status']==='pending'&&!isset($oPreflight->meta['_gor_plan']),'invalid POS plan does not freeze editable order');
